mapper.select:
SELECT DISTINCT bmr.id, bmr.reserve_name, bmr.room_id, bmr.room_name, bmr.start_time, bmr.end_time, bmr.reserve_uid, bmr.reserve_uname, bmr.reserve_staffid, bmr.in_valid_flag, bmr.cancel_flag, bmr.status, CASE WHEN status IN(10,20) THEN 1 ELSE 2 END AS status2, bm.space_id FROM bbx_meeting_reserve bmr LEFT JOIN bbx_meeting_reserve_sign s ON bmr.id = s.reserve_id LEFT JOIN bbx_meeting_room bm ON bmr.room_id = bm.id
AND bmr.tenant_id =#{condition.tenantId}
AND (bmr.reserve_uid = #{condition.userId} OR s.sign_uid = #{condition.userId})
AND bmr.cancel_flag =#{condition.cancelFlag}
AND (#{condition.startTime} <= bmr.end_time and #{condition.endTime} >= bmr.start_time)
AND bmr.reserve_name like concat('%',#{condition.reserveName},'%')
AND bmr.room_id in
#{roomId}
AND bmr.draft = 0
ORDER BY bmr.cancel_flag ASC,status2 ASC, CASE WHEN bmr.status = 30 THEN bmr.start_time ELSE NULL END DESC, CASE WHEN bmr.status != 30 THEN bmr.start_time ELSE NULL END ASC

SELECT COUNT(DISTINCT bmr.id) FROM bbx_meeting_reserve bmr LEFT JOIN bbx_meeting_reserve_sign s ON bmr.id = s.reserve_id
AND bmr.tenant_id =#{condition.tenantId}
AND (bmr.reserve_uid = #{condition.userId} OR s.sign_uid = #{condition.userId})
AND bmr.cancel_flag =#{condition.cancelFlag}
AND (#{condition.startTime} <= bmr.end_time and #{condition.endTime} >= bmr.start_time)
AND bmr.draft = 0

select bmr.id, bmr.room_id, bmr.start_time, bmr.end_time, bmr.reserve_name, bmr.reserve_uid, bmr.reserve_uname, bmr.reserve_staffid, bmr.in_valid_flag, bmr.status from bbx_meeting_reserve bmr JOIN bbx_meeting_room bm ON bmr.room_id = bm.id
AND bmr.tenant_id =#{condition.tenantId}
AND bm.room_name like concat('%',#{condition.roomName},'%')
AND bmr.room_id =#{condition.roomId}
AND bmr.room_id in
#{roomId}
AND (#{condition.endTime} >= bmr.end_time and #{condition.startTime} <= bmr.start_time)
AND bmr.cancel_flag =#{condition.cancelFlag}
AND bmr.draft = 0
order by bmr.start_time

select distinct bmr.id, bmr.room_name, bmr.reserve_name, bmr.room_id, bmr.start_time, bmr.end_time, bm.space_id from bbx_meeting_reserve bmr JOIN bbx_meeting_room bm ON bmr.room_id = bm.id JOIN bbx_meeting_reserve_sign bmrs ON bmr.id = bmrs.reserve_id
AND bmr.tenant_id =#{condition.tenantId}
AND bmr.room_name like concat('%',#{condition.roomName},'%')
AND bmr.reserve_name like concat('%',#{condition.reserveName},'%')
AND bmr.room_id =#{condition.roomId}
AND (bmr.reserve_uname like concat('%',#{condition.reserveUname},'%') or bmr.reserve_staffid =#{condition.reserveUname})
AND bmrs.sign_uid=#{condition.userId}
AND (#{condition.startTime} <= bmr.end_time and #{condition.endTime} >= bmr.start_time)
AND bm.space_id in
#{spaceId}
AND bmr.draft = 0
order by bmr.start_time DESC

WITH week_dates AS ( SELECT TRUNC(SYSDATE, 'IW') - 1 + (LEVEL - 1) AS day_date FROM DUAL CONNECT BY LEVEL <= 7 )
SELECT w.day_date AS date, COALESCE(COUNT(m.id), 0) AS count FROM week_dates w LEFT JOIN bbx_meeting_reserve m ON TRUNC(m.real_start_time) = w.day_date AND m.in_valid_flag = 0 AND m.cancel_flag = 0 AND m.deleted = 1 AND m.draft = 0
AND m.tenant_id =#{tenantId}
GROUP BY w.day_date ORDER BY w.day_date;
